(()=>{
  const form=document.querySelector('[data-r32-organizer-form]'); if(!form)return;
  const out=document.querySelector('[data-r32-organizer-output]'),routes=document.querySelector('[data-r32-organizer-routes]'),status=document.querySelector('[data-r32-organizer-status]');
  const copy=document.querySelector('[data-r32-organizer-copy]'),download=document.querySelector('[data-r32-organizer-download]'),print=document.querySelector('[data-r32-organizer-print]');
  const es=(document.documentElement.lang||'en').toLowerCase().startsWith('es'); let packet=null;
  const L=es?{
    title:'Organizador de avisos y reclamos de Franklin',empty:'Elige un tipo de documento.',built:'Organizador creado.',shown:'Fecha mostrada',deadline:'Fecha o plazo mostrado',action:'Acción indicada',verify:'Qué confirmar directamente',gather:'Qué mantener privado',questions:'Preguntas para llevar',soon:'La fecha que ingresaste está cerca. Confirme directamente qué significa ese plazo y qué regla lo controla; Franklin Navigator no calcula plazos legales ni de cobertura.',current:'La fecha ingresada no está dentro de los próximos 7 días. Aun así, confirme plazos y requisitos cambiantes en la fuente original.',privacy:'Privacidad: no subas el documento ni copies su texto aquí. Mantenga números de cuenta, reclamo, póliza, caso, paciente y otra información sensible fuera de esta herramienta.',source:'Abrir punto de partida',copy:'Organizador copiado.',copyFail:'No se pudo copiar automáticamente.'
  }:{
    title:'Franklin notice & claim organizer',empty:'Choose a document type.',built:'Organizer built.',shown:'Date shown',deadline:'Date/deadline shown',action:'Action requested',verify:'What to confirm directly',gather:'What to keep private',questions:'Questions to carry forward',soon:'The date you entered is close. Confirm directly what that date means and which rule controls it; Franklin Navigator does not calculate legal or coverage deadlines.',current:'The date you entered is not within the next 7 days. Still confirm changing deadlines and requirements at the original source.',privacy:'Privacy: do not upload the document or copy its text here. Keep account, claim, policy, case, patient and other sensitive numbers out of this tool.',source:'Open starting point',copy:'Organizer copied.',copyFail:'We couldn’t copy that automatically.'
  };
  const types={
    insurance:{en:'Insurance / coverage / denial / claim',es:'Seguro / cobertura / denegación / reclamo',route:'/prepare-connected/?needs=insurance',gather:['Keep the policy, plan, EOB, denial, claim letters and reference numbers privately on your device.','Keep photos, estimates, receipts or bills privately when relevant.'],verify:['Confirm the sender, document type and date directly from the original notice.','Confirm any appeal, proof-of-loss, documentation or response requirement with the insurer/plan or governing source.'],questions:['What does the insurer or plan say it needs next?','What date is shown and what does the relevant source say that date means?','Do I need questions for a provider, repairer, government source or attorney?']},
    legal:{en:'Court / legal / rights notice',es:'Aviso judicial / legal / de derechos',route:'/legal-help/',gather:['Keep the complete notice, envelope, attachments and any prior related notices privately.','Keep a private timeline of dates and prior responses.'],verify:['Confirm the court, agency or sender through an official source.','Confirm procedure and any stated deadline with the responsible Tennessee/local/federal source or a qualified professional.'],questions:['Does the notice state a court, agency, case type or hearing date?','What action does it explicitly request?','What should I ask a lawyer or legal-aid organization before acting?']},
    health:{en:'Health bill / EOB / referral / authorization notice',es:'Factura de salud / EOB / referencia / autorización',route:'/health-help/',gather:['Keep bills, EOBs, referral/authorization notices and insurance details privately.','Keep appointment and provider information privately when needed.'],verify:['Confirm whether the notice came from the provider, insurer/plan or another administrator.','Confirm network, authorization, appeal and billing questions directly with the relevant source.'],questions:['Is this a provider bill, an EOB, a coverage decision or an authorization/referral issue?','Which party should answer the next question first?','Is there any urgent care need separate from the paperwork issue?']},
    home:{en:'Home / property / landlord / contractor notice',es:'Aviso de vivienda / propiedad / arrendador / contratista',route:'/home-property-help/',gather:['Keep lease, contract, permit, HOA, estimate, invoice, photos and notice privately.','Keep exact property/account identifiers off this tool.'],verify:['Confirm the sender and any referenced City/County process at the official source.','Confirm changing permit, hearing, inspection, payment or response requirements directly.'],questions:['Is there an immediate safety problem separate from the notice?','Which official/property/contract source controls the next step?','Should I prepare questions for a landlord, contractor, insurer, agent or attorney?']},
    auto:{en:'Vehicle / repair / crash / title / claim notice',es:'Aviso de vehículo / reparación / choque / título / reclamo',route:'/auto-vehicle-help/',gather:['Keep estimates, invoices, photos, title/registration and insurance correspondence privately.','Keep VIN, policy and claim numbers off this tool.'],verify:['Confirm any recall, title, repair, insurer or legal requirement with the relevant source.','Separate vehicle safety from claim/payment/legal questions.'],questions:['Is the vehicle safe to drive?','Is this mainly repair, insurance, title/registration, recall or legal?','What should I ask a mechanic, insurer, agency or attorney?']},
    benefits:{en:'Government benefits / eligibility / agency notice',es:'Aviso de beneficios / elegibilidad / agencia',route:'/get-it-done/',gather:['Keep the full agency notice, benefit/account identifiers and submitted forms privately.','Keep proof documents privately until the official source says how to submit them.'],verify:['Confirm the agency and program at an official government source.','Confirm eligibility, appeal/reconsideration, document and deadline rules directly.'],questions:['Which exact program or agency issued the notice?','What action and date are stated?','What documents does the official source say are required?']}
  };
  const actions={respond:{en:'Respond or contact',es:'Responder o contactar'},appeal:{en:'Appeal / reconsideration',es:'Apelar / reconsiderar'},documents:{en:'Provide documents',es:'Entregar documentos'},pay:{en:'Payment or bill question',es:'Pregunta de pago o factura'},schedule:{en:'Schedule / attend',es:'Programar / asistir'},review:{en:'Review before signing',es:'Revisar antes de firmar'},other:{en:'Other / unclear',es:'Otro / no está claro'}};
  const fmt=d=>{if(!d)return es?'No ingresada':'Not entered';try{return new Intl.DateTimeFormat(es?'es-US':'en-US',{dateStyle:'medium'}).format(new Date(d+'T12:00:00'))}catch{return d}};
  const daysUntil=d=>{if(!d)return null;const t=new Date(d+'T12:00:00').getTime();if(!Number.isFinite(t))return null;return Math.ceil((t-Date.now())/86400000)};
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const render=()=>{
    const type=types[form.elements.type.value],action=actions[form.elements.action.value];if(!type){packet=null;out.innerHTML=`<p class="empty-state">${esc(L.empty)}</p>`;routes.replaceChildren();status.textContent=L.empty;return}
    const shown=form.elements.shown.value||'',deadline=form.elements.deadline.value||'',n=daysUntil(deadline);const soon=n!==null&&n>=0&&n<=7;
    packet={schemaVersion:'franklin.notice-claim-organizer.device-only.v1',release:'FR-NAV1.8.0-CANDIDATE-R33',community:'FRANKLIN_TN',submissionStatus:'NOT_SENT',documentType:form.elements.type.value,documentTypeLabel:type[es?'es':'en'],dateShown:shown||null,deadlineShown:deadline||null,action:form.elements.action.value,actionLabel:action[es?'es':'en'],deadlineProximity:soon?'WITHIN_7_DAYS_ENTERED_BY_USER':'NOT_WITHIN_7_DAYS_OR_NOT_ENTERED',gatherPrivately:type.gather,confirmDirectly:type.verify,questions:type.questions,startingRoute:type.route,privacy:{documentUpload:false,documentTextRequested:false,identifiersRequested:false,networkSubmission:false},authorityTransfer:false};
    out.innerHTML=`<div class="eyebrow">${esc(L.title)}</div><h3>${esc(packet.documentTypeLabel)}</h3><dl><dt><strong>${esc(L.shown)}</strong></dt><dd>${esc(fmt(shown))}</dd><dt><strong>${esc(L.deadline)}</strong></dt><dd>${esc(fmt(deadline))}</dd><dt><strong>${esc(L.action)}</strong></dt><dd>${esc(packet.actionLabel)}</dd></dl>${deadline?`<p class="${soon?'r32-soon':'r32-currentness'}">${esc(soon?L.soon:L.current)}</p>`:''}<h3>${esc(L.gather)}</h3><ul>${type.gather.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${esc(L.verify)}</h3><ul>${type.verify.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${esc(L.questions)}</h3><ul>${type.questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="r32-private">${esc(L.privacy)}</p>`;
    routes.replaceChildren();const a=document.createElement('a');a.href=type.route;a.innerHTML=`<strong>${esc(L.source)}</strong><br><span>${esc(type[es?'es':'en'])}</span><div class="r32-link-note">${es?'Los horarios, plazos, elegibilidad, tarifas y datos de contacto pueden cambiar. Confirme antes de actuar.':'Schedules, deadlines, eligibility, fees and contact details can change. Confirm before acting.'}</div>`;routes.append(a);
    status.textContent=L.built;copy.disabled=download.disabled=print.disabled=false;out.focus();window.FranklinProductHealth?.record('notice_organizer_built');
  };
  form.addEventListener('submit',e=>{e.preventDefault();render()});form.addEventListener('reset',()=>setTimeout(()=>{packet=null;out.innerHTML=`<p class="empty-state">${esc(L.empty)}</p>`;routes.replaceChildren();copy.disabled=download.disabled=print.disabled=true;status.textContent=''},0));
  copy.addEventListener('click',async()=>{if(!packet)return;try{await navigator.clipboard.writeText(JSON.stringify(packet,null,2));status.textContent=L.copy}catch{status.textContent=L.copyFail}});
  download.addEventListener('click',()=>{if(!packet)return;const blob=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=es?'franklin-organizador-aviso.json':'franklin-notice-organizer.json';a.click();URL.revokeObjectURL(url)});
  print.addEventListener('click',()=>packet&&window.print());
})();
